function newManagement(){const templates=Object.fromEntries(Object.entries(managementPresetRights).map(([k,rights])=>[k,{id:k,name:managementPresetNames[k],version:1,rights:[...rights],history:[{version:1,name:managementPresetNames[k],reason:"Исходный учебный шаблон",rights:[...rights],actor:'STAFF-201'}]}]));return {tab:'staff',query:'',staffStatus:'all',staff:null,templates,template:'operations',roleDraft:null,roleRaw:null,assignRaw:null,assignDraft:null,checked:null,revokeReview:null,assignments:Object.fromEntries(managementStaff.map(([id,,,role])=>[id,{template:role,version:1,rights:role==='owner'?managementPermissions.map(p=>p[0]):[...managementPresetRights[role]],venue:'both',environment:'paper',expires:'',revision:1,status:'active'}])),sessions:{},approvals:{},operation:null,events:[],detail:null,notice:null,error:null,outcome:'confirmed',revoked:false,stale:false,clock:'2026-10-26T12:00',auditQuery:'',auditResult:'all',auditFrom:'2026-10-17',auditTo:'2026-10-26',exportPreview:false};}
let management=newManagement();
const mn=(ru,en)=>pl(ru,en);
const managementSelect=(id,label,values,current,disabled=false)=>feedbackSelect(id,label,values,current,disabled).replace('<select id=', '<select name="'+id+'" id=');
const mb=(ru,en,action,attrs='',primary=false,cls='')=>`<button type="button" class="${cls||('btn'+(primary?' primary':''))}" data-management="${action}" ${attrs}>${mn(ru,en)}</button>`;
function managementAccess(){const role=state.role,owner=!!account?.logged&&['ownerA','ownerB'].includes(role),lead=!!account?.logged&&role==='lead',audit=!!account?.logged&&role==='audit',ops=!!account?.logged&&role==='ops';return {read:owner||lead||audit,edit:(owner||lead)&&!management.revoked,audit:owner||lead||audit,export:owner&&!management.revoked,security:owner&&!management.revoked,activate:(owner||lead)&&!management.revoked,controls:owner||lead||audit||ops,owner,grant:owner?managementPermissions.map(p=>p[0]):lead?managementPresetRights.lead:[]};}
const managementBusy=()=>management.operation&&['pending','unknown'].includes(management.operation.status);
function managementError(ru,en){management.error=[ru,en];return false;}
function managementLog(action,object,before,after,result='confirmed'){management.events.push(Object.freeze({id:'AUD-DEMO-'+(management.events.length+1),at:management.clock+'Z',actor:actor().id,role:state.role,action,object,before:structuredClone(before),after:structuredClone(after),result}));}
const managementStaffName=id=>{const p=managementStaff.find(x=>x[0]===id);return p?mn(p[1],p[2]):id;};
const managementRightName=k=>{const p=managementPermissions.find(p=>p[0]===k);return p?mn(p[3],p[4]):mn('Неделегируемое действие','Non-delegable action');};
function managementAssignmentName(g){const t=management.templates[g.template];return g.name||t?.history.find(v=>v.version===g.version)?.name||t?.name||['Владелец','Owner'];}
function managementAssignment(id){const a=management.assignments[id];return {...a,status:a.status==='revoked'?'revoked':a.expires&&a.expires<=management.clock?'expired':a.status};}
function managementStatus(s){return mn(({active:'Действует',blocked:'Аккаунт заблокирован',revoked:'Назначение отозвано',expired:'Срок истёк',pending:'Ожидается результат',unknown:'Результат неизвестен',confirmed:'Подтверждено',failed:'Подтверждённый отказ',conflict:'Данные изменились'})[s]||s,({active:'Active',blocked:'Account blocked',revoked:'Assignment revoked',expired:'Expired',pending:'Awaiting result',unknown:'Outcome unknown',confirmed:'Confirmed',failed:'Confirmed failure',conflict:'Data changed'})[s]||s);}
const managementDigest=x=>JSON.stringify(x);
function managementScope(venue){return venue==='both'?mn('Polymarket + Limitless','Polymarket + Limitless'):venue;}
function managementAllowedRights(rights){const a=managementAccess();if(!Array.isArray(rights)||!rights.length||rights.some(k=>!a.grant.includes(k)))return false;const deps={'support.reply':'support.read','support.assign':'support.read','feedback.manage':'support.read','incidents.manage':'incidents.read','reconciliation.run':'reconciliation.read','data.draft':'data.read','data.diagnose':'data.read','content.edit':'content.read','content.publish':'content.edit','marketing.segment':'content.read','marketing.test':'content.edit','marketing.publish':'marketing.test','roles.edit':'staff.read','staff.assign':'staff.read','staff.revoke':'staff.read','audit.export':'audit.read'};return rights.every(k=>!deps[k]||rights.includes(deps[k]));}
function managementSaveRole(values){if(!managementAccess().edit||managementBusy())return false;const name=String(values.name||'').trim(),rights=[...new Set(values.rights||[])].sort(),reason=String(values.reason||'').trim();if(name.length<3||name.length>80||/owner|владелец/i.test(name)||!managementAllowedRights(rights)||reason.length<4||reason.length>500)return managementError('Нужны название, причина (4–500 символов) и допустимый набор прав. Действия требуют права просмотра; полномочия владельца не делегируются.','Provide a name, a reason (4–500 characters) and permitted rights. Actions require viewing rights; owner powers cannot be delegated.');const selected=management.templates[management.template],custom=selected.id.startsWith('custom-'),id=custom?selected.id:'custom-'+(Object.keys(management.templates).filter(k=>k.startsWith('custom-')).length+1);management.roleDraft={id,name:[name,name],base:custom?selected.version:0,rights,reason,actor:actor().id};return true;}
function managementPublishRole(){const a=managementAccess(),d=management.roleDraft;if(!a.edit||!d||managementBusy()||!managementAllowedRights(d.rights)||d.actor!==actor().id||d.base!==(management.templates[d.id]?.version||0))return managementError('Проверьте свежую версию шаблона и свои права.','Check the latest template version and your permissions.');const old=management.templates[d.id];management.templates[d.id]={id:d.id,name:d.name,version:d.base+1,rights:[...d.rights],history:[...(old?.history||[]),{version:d.base+1,name:[...d.name],reason:d.reason,rights:[...d.rights],actor:actor().id}]};managementLog(['Сохранена версия шаблона','Template version saved'],d.id,old?{version:old.version,name:old.name,rights:old.rights}:null,{version:d.base+1,name:d.name,rights:d.rights,reason:d.reason});management.template=d.id;management.roleDraft=null;management.roleRaw=null;management.notice=['Шаблон сохранён. Назначения сотрудников не изменились.','Template saved. Employee assignments are unchanged.'];return true;}
function managementCheckAssignment(values){const a=managementAccess(),id=management.staff,t=management.templates[values.template],current=managementAssignment(id);management.checked=null;management.revokeReview=null;if(!managementCanChange(id)||!id||id===actor().id||managementStaff.find(s=>s[0]===id)?.[3]==='owner'||current.status==='blocked'||!t||!managementAllowedRights(t.rights)||values.environment!=='paper'||!['both','Polymarket','Limitless'].includes(values.venue)||!values.reason?.trim()||values.reason.trim().length<4||values.reason.length>500||values.expires&&(Number.isNaN(Date.parse(values.expires))||values.expires<=management.clock))return managementError('Проверьте получателя, права, область, срок и причину. Себе и владельцам здесь назначение не меняют; заблокированный аккаунт требует отдельного восстановления.','Check recipient, rights, scope, expiry and reason. Self and owner assignments cannot be changed here; blocked accounts need separate recovery.');management.assignDraft={staff:id,template:t.id,name:[...t.name],version:t.version,rights:[...t.rights],venue:values.venue,environment:'paper',expires:values.expires||'',reason:values.reason,revision:current.revision,actor:actor().id};management.checked=managementDigest(management.assignDraft);return true;}
function managementSubmit(kind){const a=managementAccess(),x=management;if(managementBusy())return managementError('Проверьте результат прежней операции. Повторная отправка недоступна.','Check the existing operation. Resubmission is unavailable.');let payload;
 if(kind==='assignment'){payload=x.assignDraft;const t=payload&&x.templates[payload.template];if(!a.edit||!payload||x.checked!==managementDigest(payload)||payload.actor!==actor().id||payload.staff===actor().id||!managementAllowedRights(payload.rights)||!t||t.version!==payload.version||managementAssignment(payload.staff).revision!==payload.revision||x.stale||payload.expires&&payload.expires<=x.clock)return managementError('Назначение изменилось, срок истёк или проверка устарела. Сравните заново.','Assignment changed, expiry passed or review is stale. Compare again.');}
 else if(kind==='revoke'){payload=x.revokeReview;if(!payload||payload.staff!==x.staff||payload.actor!==actor().id||payload.revision!==managementAssignment(payload.staff).revision||!managementCanChange(payload.staff)||payload.reason!==x.assignRaw?.reason||x.stale)return managementError('Проверьте получателя и последствия отзыва заново.','Review the recipient and revocation effects again.');}
 else return false;
 x.operation={id:'ACCESS-DEMO-'+(x.events.length+1),kind,payload:structuredClone(payload),actor:actor().id,status:'pending',applied:false};x.revokeReview=null;managementLog(['Команда принята','Command accepted'],payload.staff,null,{kind},'pending');return managementResolve();}
function managementCanChange(id){const a=managementAccess(),g=management.assignments[id];return !!g&&a.edit&&id!==actor().id&&managementStaff.find(s=>s[0]===id)?.[3]!=='owner'&&(a.owner||g.rights.every(k=>a.grant.includes(k)));}
function managementResolve(){const x=management,op=x.operation;if(!op||!['pending','unknown'].includes(op.status))return false;const next=x.outcome;if(!['pending','unknown','confirmed','failed','conflict'].includes(next))return false;if(['pending','unknown'].includes(next)){if(op.status!==next)managementLog(['Результат ещё не подтверждён','Outcome remains unconfirmed'],op.payload.staff,null,{operation:op.id},next);op.status=next;return true;}op.status=next;if(next!=='confirmed'){x.checked=null;managementLog(['Результат команды','Command outcome'],op.payload.staff,null,{operation:op.id},next);return true;}const p=op.payload;if(op.actor!==actor().id||x.stale||!managementCanChange(p.staff)||managementAssignment(p.staff).revision!==p.revision||op.kind==='assignment'&&(!managementAllowedRights(p.rights)||x.templates[p.template]?.version!==p.version||p.expires&&p.expires<=x.clock)){op.status='conflict';x.checked=null;managementLog(['Команда не применена: проверка устарела','Command not applied: stale review'],p.staff,null,{operation:op.id},'conflict');return managementError('Права, версия или срок изменились. Действие не применено.','Permissions, version or expiry changed. Action was not applied.');}if(op.applied)return false;const before=managementAssignment(p.staff);
 if(op.kind==='assignment')x.assignments[p.staff]={template:p.template,name:[...p.name],version:p.version,rights:[...p.rights],venue:p.venue,environment:p.environment,expires:p.expires,revision:p.revision+1,status:'active'};
 else{x.assignments[p.staff].status='revoked';x.assignments[p.staff].revision++;x.sessions[p.staff]='closed';x.approvals[p.staff]='revoked';}
 op.applied=true;managementLog(op.kind==='assignment'?['Назначение применено','Assignment applied']:['Назначение отозвано','Assignment revoked'],p.staff,before,{...managementAssignment(p.staff),reason:p.reason});x.checked=null;return true;}
function managementNav(){const a=managementAccess();return a.read?mb('Сотрудники и права','Staff and access','open',state.route==='management'?'aria-current="page"':'',false,'sub '+(state.route==='management'?'selected':'')):'';}
function managementTabs(){const a=managementAccess();return `<div class="tabs" role="tablist">${[['staff','Сотрудники','Staff',a.read],['roles','Шаблоны ролей','Role templates',a.read],['audit','Журнал','Audit log',a.audit],].filter(x=>x[3]).map(([key,ru,en])=>`<button role="tab" aria-selected="${management.tab===key}" class="${management.tab===key?'active':''}" data-management="tab" data-tab="${key}">${mn(ru,en)}</button>`).join('')}</div>`;}
function managementPage(){const a=managementAccess();if(!a.read)return heading(mn('Раздел недоступен','Section unavailable'));return `${heading(mn('Сотрудники и права','Staff and access'),mn('Кто может выполнять действия, где и до какого срока','Who can act, where and until when'))}<div class="management-workspace">${managementTabs()}${management.error?`<p class="error" role="alert">${escape(mn(...management.error))}</p>`:''}${management.notice?`<p class="support-notice" role="status">${escape(mn(...management.notice))}</p>`:''}${({staff:managementStaffPage,roles:managementRolesPage,audit:managementAuditPage})[management.tab]()}${managementOperationPage()}${managementScenarios()}</div>`;}
function managementStaffPage(){const x=management,a=managementAccess();if(x.staff)return managementStaffDetail();const list=managementStaff.filter(s=>(s.join(' ').toLowerCase().includes(x.query.toLowerCase()))&&(x.staffStatus==='all'||managementAssignment(s[0]).status===x.staffStatus));return `<form id="management-staff-filter" class="content-filters">${cfield('query','Имя или ID','Name or ID',x.query)}${managementSelect('staffStatus',mn('Состояние доступа','Access status'),[['all',mn('Все','All')],...['active','blocked','revoked','expired'].map(k=>[k,managementStatus(k)])],x.staffStatus)}<button class="btn">${mn('Найти','Find')}</button>${mb('Сбросить','Reset','reset')}</form>${dtable([mn('Сотрудник','Employee'),mn('Назначение','Assignment'),mn('Область','Scope'),mn('Срок / статус','Expiry / status')],list.map(s=>{const g=managementAssignment(s[0]);return `<tr><td>${mb(mn(s[1],s[2]),mn(s[1],s[2]),'staff',`data-id="${s[0]}"`,false,'user-link')}<small>${s[0]}</small></td><td>${s[3]==='owner'?mn('Системный владелец','System owner'):escape(mn(...managementAssignmentName(g)))} · v${g.version}</td><td>Paper Alpha · ${managementScope(g.venue)}</td><td>${g.expires||mn('Без срока','No expiry')}<small>${managementStatus(g.status)}</small></td></tr>`;}))}${!list.length?`<p>${mn('Сотрудники не найдены. Измените отбор.','No staff found. Change filters.')}</p>`:''}<p class="muted">${mn('Владельцев два. Это разные люди и разные подтверждения. Шаблон роли сам по себе не выдаёт доступ.','There are two owners with separate identities and approvals. A role template does not grant access by itself.')}</p>`;}
function managementRightsList(rights){return `<ul class="management-rights">${rights.map(k=>`<li>${escape(managementRightName(k))}</li>`).join('')}</ul>`;}
function managementStaffDetail(){const x=management,id=x.staff,g=managementAssignment(id),a=managementAccess(),isOwner=managementStaff.find(s=>s[0]===id)[3]==='owner',can=managementCanChange(id),raw=x.assignRaw||{template:g.template,venue:g.venue,environment:'paper',expires:g.expires,reason:''};return `${mb('К сотрудникам','Back to staff','staff-back')}<h2>${escape(managementStaffName(id))} <small>${id}</small></h2><p><span class="badge">${managementStatus(g.status)}</span> · ${mn('Версия назначения','Assignment revision')} ${g.revision}</p><section class="panel"><h3>${mn('Сейчас доступно','Current access')}</h3><p>Paper Alpha · ${managementScope(g.venue)} · ${g.expires||mn('Без срока','No expiry')}</p>${isOwner?`<p>${mn('Системная роль владельца. Редактор шаблонов не создаёт и не передаёт эти полномочия.','System owner role. The template editor cannot create or transfer these powers.')}</p>`:`<details class="management-details"><summary>${mn('Разрешённые действия','Permitted actions')} · ${g.status==='active'?g.rights.length:0}</summary>${managementRightsList(g.status==='active'?g.rights:[])}</details>`}${g.status!=='active'?`<p>${mn('Назначение не даёт права выполнять новые действия.','This assignment does not permit new actions.')}</p>`:''}</section>${can?`<section class="panel"><h3>${mn('Предложить новое назначение','Propose a new assignment')}</h3><form id="management-assignment-form" class="content-columns">${managementSelect('template',mn('Шаблон и версия','Template and version'),Object.values(x.templates).map(t=>[t.id,mn(...t.name)+' · v'+t.version]),raw.template)}${managementSelect('venue',mn('Площадки','Venues'),[['both','Polymarket + Limitless'],['Polymarket','Polymarket'],['Limitless','Limitless']],raw.venue)}${managementSelect('environment',mn('Среда','Environment'),[['paper','Paper Alpha']],raw.environment)}${cfield('expires','Действует до · UTC (пусто — без срока)','Valid until · UTC (empty — no expiry)',raw.expires,'datetime-local')}${cfield('reason','Причина изменения','Change reason',raw.reason)}<button class="btn primary">${mn('Проверить и сравнить права','Check and compare access')}</button></form><p class="muted">${mn('Сохранение шаблона не меняет сотрудника. Применяется выбранная версия с этой областью и сроком.','Saving a template does not change staff. The selected version applies with this scope and expiry.')}</p></section>`:`<p class="support-notice">${mn(id===actor().id?'Свои полномочия здесь менять нельзя.':'В этом назначении изменение недоступно.',id===actor().id?'You cannot change your own permissions here.':'Changes are unavailable in this assignment.')}</p>`}${x.checked&&x.assignDraft?.staff===id?managementAssignmentPreview(g):''}${can&&g.status==='active'?mb('Подготовить отзыв доступа','Review access revocation','review-revoke'):''}${x.revokeReview?.staff===id?`<section class="panel"><h3>${mn('Подтвердить отзыв доступа','Confirm access revocation')}</h3><p>${escape(managementStaffName(id))} · ${id} · v${g.revision}</p><p>${mn('Назначение перестанет действовать, все сеансы сотрудника завершатся, неиспользованные подтверждения будут отозваны. Уже отправленные операции продолжат сверку.','The assignment will stop granting access, all employee sessions will end and unused approvals will be revoked. Submitted operations remain under reconciliation.')}</p><p>${escape(x.revokeReview.reason)}</p>${mb('Отозвать доступ и завершить сеансы','Revoke access and end sessions','revoke','',true)}${mb('Отмена','Cancel','cancel-revoke')}</section>`:''}${x.sessions[id]?`<section class="panel"><h3>${mn('Последствия отзыва','Revocation effects')}</h3><p>${mn('Сеансы завершены. Неиспользованные подтверждения отозваны. Уже отправленные внешние операции продолжают сверку.','Sessions closed. Unused approvals revoked. Submitted external operations remain under reconciliation.')}</p></section>`:''}`;}
function managementAssignmentPreview(g){const d=management.assignDraft,baseline=g.status==='active'?g.rights:[],add=d.rights.filter(k=>!baseline.includes(k)),remove=baseline.filter(k=>!d.rights.includes(k));return `<section class="panel"><h3>${mn('Что изменится','What changes')}</h3><p><strong>${managementStaffName(d.staff)} · ${d.staff}</strong></p><dl class="account-facts"><div><dt>${mn('Шаблон','Template')}</dt><dd>${escape(mn(...d.name))} · v${d.version}</dd></div><div><dt>${mn('Площадки: было → станет','Venues: before → after')}</dt><dd>${managementScope(g.venue)} → ${managementScope(d.venue)}</dd></div><div><dt>${mn('Срок: было → станет','Expiry: before → after')}</dt><dd>${g.expires||mn('Без срока','No expiry')} → ${d.expires||mn('Без срока','No expiry')}</dd></div></dl><p>${mn('Причина','Reason')}: ${escape(d.reason)}</p><div class="content-columns"><section><h4>${mn('Добавится','Added')}</h4>${add.length?managementRightsList(add):mn('Новых прав нет','No new permissions')}</section><section><h4>${mn('Будет убрано','Removed')}</h4>${remove.length?managementRightsList(remove):mn('Удалений нет','Nothing removed')}</section></div><p>${mn('Сохранится прав','Retained permissions')}: ${d.rights.length-add.length}. ${mn('Новый срок и область заменят прежние для этого назначения.','The new expiry and scope replace the old values for this assignment.')}</p>${!managementBusy()?mb('Применить это назначение','Apply this assignment','apply-assignment','',true):''}</section>`;}
function managementRolesPage(){const x=management,a=managementAccess(),t=x.templates[x.template],raw=x.roleRaw||x.roleDraft||{name:mn(...t.name)+(t.id.startsWith('custom-')?'':' · '+mn('копия','copy')),rights:t.rights,reason:''};return `<div class="management-template-list">${managementSelect('management-template',mn('Выберите шаблон','Choose a template'),Object.values(x.templates).map(t=>[t.id,mn(...t.name)+' · v'+t.version]),x.template)}</div><h2>${escape(mn(...t.name))} · v${t.version}</h2><p>${mn('Изменение создаёт версию кастомного шаблона. Назначения не обновляются автоматически.','Changes create a custom template version. Assignments do not update automatically.')}</p><form id="management-role-form"><fieldset ${a.edit?'':'disabled'}>${cfield('name',t.id.startsWith('custom-')?'Название роли':'Название новой роли',t.id.startsWith('custom-')?'Role name':'New role name',raw.name)}${cfield('reason','Зачем нужны эти права','Why these permissions are needed',raw.reason)}<div class="management-permissions">${[...new Set(managementPermissions.map(p=>p[1]))].map(group=>`<fieldset><legend>${mn(group,managementPermissions.find(p=>p[1]===group)[2])}</legend>${managementPermissions.filter(p=>p[1]===group).map(([k,,,ru,en])=>`<label><input type="checkbox" name="rights" value="${k}" ${(raw.rights||[]).includes(k)?'checked':''} ${a.grant.includes(k)?'':'disabled'}>${mn(ru,en)}${!a.grant.includes(k)?` <small>${mn('нельзя выдать','cannot grant')}</small>`:''}</label>`).join('')}</fieldset>`).join('')}</div><p class="support-notice">${mn('Не делегируются: статус владельца, публикация денежных условий, выплаты, ключи сервиса, сделки за пользователя и повтор неизвестной операции. Экспорт не входит в просмотр.','Not delegated: owner status, monetary policy publication, payouts, service keys, trading for a user or resending an unknown operation. Export is separate from viewing.')}</p>${a.edit?`<button class="btn">${mn('Подготовить версию шаблона','Prepare template version')}</button>`:''}</fieldset></form><details class="management-details"><summary>${mn('История выбранного шаблона','Selected template history')} · ${t.history.length}</summary>${t.history.map(h=>`<p>v${h.version} · ${h.actor} · ${escape(mn(...(h.name||t.name)))} · ${escape(h.reason||mn('Исходный шаблон','Initial template'))} · ${h.rights.length} ${mn('разрешений','permissions')}</p>`).join('')}</details>${x.roleDraft?`<section class="panel"><h3>${mn('Подготовлена версия','Prepared version')} ${x.roleDraft.base+1}</h3>${managementRightsList(x.roleDraft.rights)}${mb('Сохранить новую версию шаблона','Save new template version','save-template','',true)}</section>`:''}`;}
function managementActorRole(role){return ['ownerA','ownerB'].includes(role)?mn('Владелец','Owner')+' '+(role==='ownerA'?'A':'B'):mn(...(managementPresetNames[role==='ops'?'operations':role]||['Назначение','Assignment']));}
function managementAuditRows(){const x=management;return x.events.filter(e=>e.at.slice(0,10)>=x.auditFrom&&e.at.slice(0,10)<=x.auditTo&&(x.auditResult==='all'||e.result===x.auditResult)&&[e.id,e.actor,e.object,...e.action].join(' ').toLowerCase().includes(x.auditQuery.toLowerCase()));}
function managementAuditPage(){const x=management,a=managementAccess(),rows=managementAuditRows();return `<h2>${mn('Журнал действий','Action log')}</h2><p>${mn('Учебные записи текущего прохода. В рабочем сервисе журнал хранится независимо с проверкой целостности. Этот макет не доказывает такую защиту.','Synthetic records of this walkthrough. Production audit requires independent storage and integrity checks. This prototype does not prove those protections.')}</p><form id="management-audit-filter" class="content-columns">${cfield('auditQuery','Сотрудник, объект или действие','Actor, object or action',x.auditQuery)}${managementSelect('auditResult',mn('Результат','Outcome'),[['all',mn('Все','All')],...['confirmed','pending','unknown','failed','conflict'].map(k=>[k,managementStatus(k)])],x.auditResult)}${cfield('auditFrom','С · UTC','From · UTC',x.auditFrom,'date')}${cfield('auditTo','По · UTC','To · UTC',x.auditTo,'date')}<button class="btn">${mn('Применить отбор','Apply filters')}</button></form>${dtable([mn('Время UTC','Time UTC'),mn('Сотрудник','Actor'),mn('Действие / объект','Action / object'),mn('Результат','Outcome')],rows.map(e=>`<tr><td>${mb(e.id,e.id,'audit-detail',`data-id="${e.id}"`)}<small>${e.at}</small></td><td>${e.actor}<small>${escape(managementActorRole(e.role))}</small></td><td>${mn(...e.action)}<small>${e.object}</small></td><td>${managementStatus(e.result)}</td></tr>`))}${!rows.length?`<p>${mn('В этой выборке нет учебных событий. Это не утверждение об отсутствии событий в реальном сервисе.','No synthetic events in this selection. This does not claim the real service has no events.')}</p>`:''}${a.export?mb('Подготовить разрешённую выгрузку','Prepare permitted export','export'):''}${x.exportPreview?`<section class="panel"><h3>${mn('Предпросмотр учебной выгрузки','Synthetic export preview')}</h3><p>${x.exportPreview.length} ${mn('записей, только текущий отбор. Контакты, ключи и секреты исключены.','records, current selection only. Contacts, keys and secrets excluded.')}</p><p>${x.exportPreview.join(', ')||'—'}</p></section>`:''}${x.detail?managementAuditDetail():''}`;}
function managementAuditDetail(){const e=management.events.find(e=>e.id===management.detail);if(!e)return '';const format=v=>!v?mn('Не было','None'):Object.entries(v).filter(([k])=>['name','version','revision','template','venue','environment','expires','status','rights','kind','object','reason'].includes(k)).map(([k,v])=>`<div><dt>${({name:mn('Название','Name'),version:mn('Версия','Version'),revision:mn('Версия назначения','Assignment revision'),template:mn('Шаблон','Template'),venue:mn('Площадка','Venue'),environment:mn('Среда','Environment'),expires:mn('Срок','Expiry'),status:mn('Состояние','Status'),rights:mn('Права','Permissions'),kind:mn('Тип','Type'),object:mn('Объект','Object'),reason:mn('Причина','Reason')})[k]}</dt><dd>${Array.isArray(v)?(k==='name'?escape(mn(...v)):managementRightsList(v)):escape(k==='status'?managementStatus(v):String(v||'—'))}</dd></div>`).join('');return `<section class="panel"><h3>${e.id} · ${mn(...e.action)}</h3><p>${e.actor} · ${e.at}</p><div class="content-columns"><section><h4>${mn('До изменения','Before')}</h4><dl>${format(e.before)}</dl></section><section><h4>${mn('После изменения','After')}</h4><dl>${format(e.after)}</dl></section></div>${mb('Закрыть подробности','Close details','audit-close')}</section>`;}
function managementOperationPage(){const op=management.operation;if(!op)return '';return `<section class="panel" aria-live="polite"><h3>${mn('Результат команды','Command outcome')} · ${op.id}</h3><p>${managementStatus(op.status)} · ${op.actor}</p>${managementBusy()?`<p>${mn('Принято не означает применено. Проверьте прежнюю операцию; повторная отправка запрещена.','Accepted does not mean applied. Check the original operation; resubmission is blocked.')}</p>${mb('Проверить прежнюю операцию','Check existing operation','reconcile','',true)}`:''}</section>`;}
function managementScenarios(){return `<details class="account-test"><summary>${mn('Учебные состояния — не рабочие настройки','Synthetic states — not operational settings')}</summary>${managementSelect('management-outcome',mn('Результат команды','Command result'),['confirmed','pending','unknown','failed','conflict'].map(k=>[k,managementStatus(k)]),management.outcome)}<label><input type="checkbox" data-management-state="revoked" ${management.revoked?'checked':''}> ${mn('Право управляющего отозвано','Manager permission revoked')}</label><label><input type="checkbox" data-management-state="stale" ${management.stale?'checked':''}> ${mn('Версия изменилась после проверки','Version changed after review')}</label>${mb('Показать истечение срока','Show expiry','expire')}</details>`;}
function managementAction(action,el={dataset:{}}){const x=management,a=managementAccess(),ds=el.dataset;x.error=null;x.notice=null;if(!a.read)return false;if(action==='open'){x.tab='staff';navigate('management');return true;}if(action==='tab'){if(!['staff','roles','audit'].includes(ds.tab)||!a.read)return false;x.tab=ds.tab;}
 else if(action==='staff'){if(!a.read||!management.assignments[ds.id])return false;x.staff=ds.id;x.revokeReview=null;x.assignRaw=null;x.assignDraft=null;x.checked=null;x.proof=null;}
 else if(action==='staff-back')x.staff=null;
 else if(action==='reset'){x.query='';x.staffStatus='all';}
 else if(action==='template'){if(!x.templates[ds.id])return false;x.template=ds.id;x.roleDraft=null;x.roleRaw=null;}
 else if(action==='save-template')return managementPublishRole();
 else if(action==='apply-assignment')return managementSubmit('assignment');
 else if(action==='review-revoke'){if(!managementCanChange(x.staff)||!x.assignRaw?.reason?.trim()||x.assignRaw.reason.trim().length<4||managementBusy())return managementError('Укажите причину отзыва (минимум 4 символа) в форме выше.','Enter a revocation reason (at least 4 characters) in the form above.');x.revokeReview={staff:x.staff,revision:managementAssignment(x.staff).revision,reason:x.assignRaw.reason,actor:actor().id};}
 else if(action==='cancel-revoke')x.revokeReview=null;
 else if(action==='revoke')return managementSubmit('revoke');
 else if(action==='reconcile')return managementResolve();
 else if(action==='audit-detail'){if(!a.audit)return false;x.detail=ds.id;}
 else if(action==='audit-close')x.detail=null;
 else if(action==='export'){if(!a.export)return false;x.exportPreview=managementAuditRows().map(e=>e.id);managementLog(['Подготовлена выгрузка','Export prepared'],'audit',null,{records:x.exportPreview.length});}
 else if(action==='expire'){x.clock='2027-01-01T00:00';x.checked=null;x.proof=null;}
 else return false;return true;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-management]');if(!el||el.disabled)return;managementAction(el.dataset.management,el);render();});
document.addEventListener('input',e=>{const form=e.target.closest('form');if(!form?.id.startsWith('management-'))return;const fd=new FormData(form),v=Object.fromEntries(fd);if(form.id==='management-role-form'){v.rights=fd.getAll('rights');management.roleRaw=v;management.roleDraft=null;}else if(form.id==='management-assignment-form'){management.assignRaw=v;management.checked=null;management.revokeReview=null;}});
document.addEventListener('change',e=>{if(e.target.id==='management-template'){managementAction('template',{dataset:{id:e.target.value}});render();return;}if(e.target.id==='management-outcome')management.outcome=e.target.value;else if(e.target.dataset.managementState){management[e.target.dataset.managementState]=e.target.checked;management.checked=null;management.revokeReview=null;}else return;render();});
document.addEventListener('submit',e=>{if(!e.target.id.startsWith('management-'))return;e.preventDefault();const fd=new FormData(e.target),v=Object.fromEntries(fd),x=management;x.error=null;x.notice=null;switch(e.target.id){case'management-staff-filter':x.query=v.query||'';x.staffStatus=v.staffStatus;break;case'management-role-form':v.rights=fd.getAll('rights');managementSaveRole(v);break;case'management-assignment-form':managementCheckAssignment(v);break;case'management-audit-filter':if(!v.auditFrom||!v.auditTo||v.auditFrom>v.auditTo){managementError('Проверьте период UTC.','Check the UTC range.');break;}Object.assign(x,v);x.exportPreview=false;break;}render();});
